(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["lt"] = {"ui":{"skip":"Pereiti prie turinio","back":"← Atgal į AI-gile","lang.button":"Kalba: {name}","lang.dialog":"Pasirink kalbą","lang.search":"Ieškoti kalbų","lang.none":"Nėra tokios kalbos","lang.notYet":"{name} dar neišversta","theme.aria":"Perjungti šviesią ir tamsią temą","theme.toLight":"Perjungti į šviesią temą","theme.toDark":"Perjungti į tamsią temą","index.title":"AI-gile: tavo dirbtinio intelekto komanda vienoje lentoje","index.description":"AI-gile yra kanban lenta dirbtinio intelekto programavimo komandoms. Jos dirba, kol tu miegi, o tau lieka vienas trumpas sąrašas: ką nuspręsti, išbandyti ir priimti.","hero.logoAlt":"AI-gile lentos piktograma","hero.h1.html":"Tavo dirbtinio intelekto komanda vienoje&nbsp;lentoje.","hero.alpha":"🐣 Uždara ankstyva alfa","hero.alphaTitle":"Dar nebaigta: ačiū, kad išbandai!","hero.lede":"Jie kuria, kol tu miegi. Pabundi ir randi vieną trumpą krūvelę: keli klausimai, keli dalykai išbandymui, vienas kitas violetinis rombas. Paspaudi, priimi ir grįžti prie kavos.","dl.windows":"Windows programa","dl.browser":"Paleisti naršyklėje","dl.soon":"Netrukus","dl.notify":"🔔 Pranešk, kai atsidarys","dl.notifySmall":"Alfa ar beta","hero.secondary":"Agile, bet komandai niekada nereikia rytinės stovimosios kavos. (Susitikimus ji vis tiek rengia.)","pitch.h2":"AI-gile tiek žodžių, kiek nori","pitch.lede":"Pasirink ilgį, nuo vieno žodžio iki 144. Kiekvienas ilgis yra atskiras aprašymas, parašytas būtent tokiam dydžiui. Vilk slankiklį arba spausk rodyklių klavišus.","pitch.rangeLabel":"Ilgis žodžiais","pitch.dice":"🎲 kita versija","pitch.words.one":"{n} žodis","pitch.words.few":"{n} žodžiai","pitch.words.other":"{n} žodžių","pitch.letters.one":"{n} raidė","pitch.letters.few":"{n} raidės","pitch.letters.other":"{n} raidžių","pitch.chars.one":"{n} simbolis","pitch.chars.few":"{n} simboliai","pitch.chars.other":"{n} simbolių","count.line.html.one":"Šiuo metu lentoje yra {n} kortelė","count.line.html.few":"Šiuo metu lentoje yra {n} kortelės","count.line.html.other":"Šiuo metu lentoje yra {n} kortelių","features.aria":"Ką ji daro","f.pile.h":"Viena krūvelė tau","f.pile.html":"<b>Tau</b> kaupia viską, kas laukia tavęs, iš visų projektų: klausimus, dalykus išbandymui, užduotis, kurias gali atlikti tik žmogus. Eilė parodo, kas toliau ir kiek tai užtruks.","f.sleep.h":"Komandos, dirbančios, kol tu miegi","f.sleep.p":"Kiekvienas projektas turi vadovą ir dirbtinio intelekto agentų komandą. Pakomentuok kortelę, ir komanda atsibunda, atlieka darbą ir grąžina jį su žingsniais, kuriuos gali atlikti ir pavargęs žmogus.","f.tester.h":"Pirmiausia tikrina dirbtinio intelekto testuotojas","f.tester.p":"Prieš tau kažką parodant, testuotojas atlieka žingsnius programos kopijoje ir parodo, ką pamatė, su ekrano nuotrauka. Peržvelk išlaikiusius ir priimk vienu paspaudimu.","f.proof.h":"Įrodymai, ne pažadai","f.proof.p":"Kiekvienas perdavimas parodo, kas pasikeitė: failus, skirtumus, ekrano nuotraukas. Nereikia atidarinėti kiekvienos programos, kad sužinotum, ar jau padaryta.","f.chat.h":"Kalbėkis su savo vadovais","f.chat.p":"Kaip Discord: juosta su viena piktograma kiekvienam projektui ir violetiniais rombais tam, kam reikia tavęs. Parašyk vadovui idėją, o jis paverčia ją kortelėmis ir planu su mygtuku ✅ Pirmyn.","f.tidy.h":"Pati susitvarko","f.tidy.p":"Susijusios kortelės sujungiamos į vieną, painūs pavadinimai sutvarkomi, o žetonų patikra palaiko kodą lengvą. Mažiau ką perjunginėti, mažiau ką galvoti.","f.private.h":"Tavo ir tavo kompiuteryje","f.private.li1":"Lenta veikia tavo paties kompiuteryje ir atsako tik tau.","f.private.li2":"Privačios žmonių žinutės šifruojamos nuo galo iki galo.","f.private.li3":"Jokių paskyrų, sekliklių ar slapukų.","f.lang.h":"Tavo kalba","f.lang.p":"Daugiau nei 120 kalbų: nuo olandų, valų ir japonų iki piratų, Yodos ir klingonų, o programuotojų žodžiams galima greitai grįžti prie anglų kalbos.","tl.aria":"Laiko juosta nuo pirmo pokalbio iki planų","tl.h2":"Nuo pirmo pokalbio iki to, kas laukia","tl.lede":"Tikros datos ir laikas tavo laiko juostoje. Po šiandien tai tik planas, be pažadėtų datų.","tl.today":"Šiandien","tl.planned":"planuojama","tl.cards.one":"{n} kortelė","tl.cards.few":"{n} kortelės","tl.cards.other":"{n} kortelių","join.h2":"Prisijunk","join.lede":"AI-gile kuria mažas žmogus ir daugybė kantrių agentų. Kol kas ji uždara: tik uždara alfa su draugais. Nori išbandyti, kai atsivers?","join.btn":"Užsiregistruoti","join.small":"Parašysime el. paštu, ir nieko daugiau","footer.tag":"AI-gile. Jokių sekliklių, jokių slapukų, jokios stovimosios kavos.","footer.licence":"Verslo licencija","footer.status":"Būsena","form.sending":"Siunčiama…","form.failed":"Nepavyko: pabandyk vėliau.","form.offline":"Nepavyko pasiekti AI-gile: pabandyk vėliau.","interest.title":"AI-gile: pranešk man, kai atsidarys alfa","interest.description":"Palik el. paštą, ir sužinosi, kada atsidarys uždara AI-gile alfa ar beta.","interest.h1":"🔔 Pranešk, kai atsidarys","interest.lede":"AI-gile yra uždaroje ankstyvoje alfoje. Palik el. paštą ir parašysime vieną kartą, kai atsiras vieta tau.","interest.email":"Tavo el. paštas","interest.which":"Kuris testas?","interest.alpha":"Uždara alfa: ankstyva, šiurkšti, daug pokyčių","interest.beta":"Beta: stabilesnė, vėliau","interest.both":"Bet kuri, kuri bus pirma","interest.submit":"Įrašykite mane į sąrašą","interest.thanks":"Ačiū! Esi sąraše.","licence.title":"AI-gile: verslo licencija","licence.description":"Naudoji AI-gile savo versle? Paprašyk nemokamos verslo licencijos.","licence.h1":"📜 Verslo licencija","licence.lede":"Naudoji AI-gile darbe? Papasakok, kas esi ir ką veiki. Jei tai daro gero, licencija nemokama.","licence.company":"Įmonė","licence.website":"Svetainė","licence.what":"Ką veiki","licence.how":"Kuo tai padeda pasauliui","licence.email":"El. paštas","licence.submit":"Pateikti","licence.thanks":"Ačiū! Atsakysime el. paštu.","status.title":"AI-gile būsena","status.h1":"AI-gile būsena","status.quiet":"Viskas ramu","status.checking":"Tikrinama…","status.offline":"Šiuo metu nepavyksta pasiekti būsenos tarnybos (bandoma iš naujo)","status.updated":"atnaujinta {ago}","status.justNow":"ką tik","status.min":"prieš {n} min.","status.hours":"prieš {n} val.","status.days":"prieš {n} d.","live.h2":"Stebėkite, kaip tai kuriama, tiesiogiai","live.caption":"Kiekviena kortelė paslėpta: matote darbo formą, o ne žodžius.","live.watching.one":"tiesiogiai: {n} stebi","live.watching.other":"tiesiogiai: {n} stebi","live.offline":"Tiesioginė lenta trumpam ilsisi. Užsukite netrukus.","live.cols":"Backlog|Reikia padaryti|Vykdoma|Komanda tikrina|Tau išbandyti|Komandai|Atlikta","live.last.now":"Paskutinė kortelė perkelta ką tik","live.last.min.one":"Paskutinė kortelė perkelta prieš {n} min.","live.last.min.other":"Paskutinė kortelė perkelta prieš {n} min.","live.last.hour.one":"Paskutinė kortelė perkelta prieš {n} val.","live.last.hour.other":"Paskutinė kortelė perkelta prieš {n} val.","live.last.day.one":"Paskutinė kortelė perkelta prieš {n} d.","live.last.day.other":"Paskutinė kortelė perkelta prieš {n} d."},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotai.","Deleguota."]},{"n":2,"texts":["Robotų kanban.","Agentai tvarkomi.","Idėjos įgyvendintos."]},{"n":3,"texts":["Kanban robotams.","Idėjos tampa funkcijomis.","Nemokamas agentų kanban."]},{"n":5,"texts":["Kanban lenta, kurią vairuoja agentai.","Tu rašai korteles. Agentai kuria.","Nemokama, vietinė, išbandyta, kiek kvailoka."]},{"n":8,"texts":["Nemokama kanban lenta, kurioje dirba dirbtinio intelekto agentai.","Užrašai idėją. Agentai ją sukuria. Tu ją priimi.","Agile vienam žmogui ir daugybei labai kantrių robotų."]},{"n":13,"texts":["Kanban lenta tavo kompiuteryje, kurioje kortelių imasi dirbtinio intelekto agentai, o tu čia vyresnysis.","Parašyk idėją. Agentų komanda ją sukuria. Testuotojas patikrina. Tau lieka tik pasakyti taip.","Jokių paskyrų, jokių sekliklių: lenta, keli robotai ir tu, kuris čia viską sprendi."]},{"n":21,"texts":["AI-gile yra kanban lenta darbui su dirbtinio intelekto programavimo agentais. Jie ima korteles, o tu jas išbandai ir priimi.","Kiekvienas projektas turi vadovą ir dirbtinio intelekto agentų komandą. Pakomentuok bet kurią kortelę, ir komanda ima dirbti.","Nemokama asmeninė užduočių lenta, veikianti tavo paties kompiuteryje, be paskyrų. Darbininkai yra robotai. Tas, kuris sako taip, esi tu."]},{"n":34,"texts":["Dedi idėjas į lentą. Dirbtinio intelekto agentų komanda paverčia jas veikiančiomis funkcijomis, išbando ir grąžina su žingsniais, kaip pačiam pabandyti. Niekas nelaikoma padaryta, kol to nepasakai tu.","AI-gile yra namie pagaminta kanban lenta, kurią Richas sukūrė su didele pagalba agentų, kuriuos ji dabar valdo. Ji nemokama, veikia tavo kompiuteryje ir dalijamasi su draugais, o ne parduodama.","Įsivaizduok įprastą kanban lentą su stulpeliais nuo Backlog iki Done, tik kortelių čia imasi dirbtinio intelekto agentai. Jie praneša apie pažangą, užstrigę klausia ir visada laukia tavo nykščio aukštyn."]},{"n":55,"texts":["AI-gile yra kanban lenta, kurioje komandą sudaro dirbtinio intelekto agentai. Kiekvienas projektas turi vadovą, kuris planuoja darbą, ir pagalbininkus, kurie jį atlieka. Kai funkcija paruošta, dirbtinio intelekto testuotojas ją išbando ir padaro ekrano nuotrauką, o tada ji patenka į tavo krūvelę. Priimk ją arba pakomentuok, ir ją perdarys.","Viskas prasidėjo nuo vieno žmogaus noro sekti daugybę dirbtinio intelekto programavimo seansų vienu metu, o išaugo į tikrą lentą. Ji veikia tavo kompiuteryje, nereikalauja paskyros ir neturi sekliklių. Ji nemokama draugams ir smalsuoliams. Ji dar nebaigta, tad tikėkis šiurkštumų ir kartais netikėtumų. Dirbame ją kasdien, po truputį, kartu su draugais, kurie ją bando.","Štai sąžininga versija. Idėjas vis tiek turi sugalvoti pats ir rezultatus vis tiek turi patikrinti pats. AI-gile padaro viską, kas tarp to: laiko korteles tvarkingai, pažadina reikiamą agentą, kai pakomentuoji, parodo, kas tiksliai pasikeitė, ir surenka viską į vieną trumpą krūvelę tau. Tau lieka smagiausia dalis: sugalvoti ir nuspręsti."]},{"n":89,"texts":["AI-gile yra nemokama kanban lenta, kurią paleidi savo kompiuteryje. Vietoj žmonių kiekvienas projektas turi dirbtinio intelekto agentų komandą: vadovą, kuris tavo idėjas paverčia kortelėmis ir planu, ir pagalbininkus, kurie kortelių imasi pagal svarbą. Kai kas nors sukurta, dirbtinio intelekto testuotojas atlieka bandymo žingsnius ir parodo, ką pamatė. Tada viskas laukia vienoje krūvelėje, pavadintoje Tau. Priimi arba pakomentuoji, ir komanda bando dar kartą. Niekas nepasiekia Done be tavęs. Visa tai vyksta tavo kompiuteryje, be paskyrų ir be jokio sekimo.","Kelios funkcijos, kurių galbūt nesitikėjai. Naktinė sargyba papildo stulpelį Ko reikia padaryti, kol tu miegi, rinkdamasi korteles, kurioms nereikia tavo atsakymo. Žetonų skaitiklis rodo, kiek agentai šiandien ir šią savaitę sunaudojo, o No Token Mode liepia jiems nustoti eikvoti. Gali rašyti draugams, o privačios žinutės šifruojamos nuo galo iki galo. Lenta kalba maždaug 120 kalbų, tarp jų olandų, flamandų, piratų ir klingonų. Nė už vieną nereikia mokėti, ir niekas čia tau nieko nebando parduoti. Viskas veikia vietoje, tavo kompiuteryje.","AI-gile yra mažas asmeninis projektas, o ne įmonė. Richas norėjo prižiūrėti kelis dirbtinio intelekto programavimo projektus neatidarinėdamas kiekvienos programos, tad jis su agentais sukūrė tam lentą, o paskui ja pačia sukūrė likusią savęs dalį. Ji yra uždaroje ankstyvoje alfoje, vadinasi, veikia, daugmaž, saujelei draugų. Nėra nei kainų puslapio, nei naujienlaiškio, nei augimo plano. Jei skamba naudinga, gali paprašyti išbandyti, kai ji kiek atsivers. Jokio spaudimo, tik lenta, kuri pamažu tampa geresnė."]},{"n":144,"texts":["AI-gile yra kanban lenta vienam žmogui ir daugybei dirbtinio intelekto agentų. Ji veikia tavo paties kompiuteryje ir yra visiškai nemokama. Pridedi projektus, ir kiekvienas gauna vadovą bei nedidelę komandą. Su vadovu kalbiesi kaip per Discord ir aprašai idėją, o jis paverčia ją kortelėmis ir planu, tada laukia, kol paspausi Pirmyn. Komanda eina per korteles pagal svarbą, naudodama paprastą komandų eilutę, sukurtą kalbos modeliams. Prieš tau ką nors grąžinant, dirbtinio intelekto testuotojas atlieka žingsnius programos kopijoje ir prideda ekrano nuotrauką. Baigtas darbas patenka į tavo krūvelę kartu su pakeistais failais ir skirtumais. Priimi jį arba paliki komentarą, ir komanda pabunda bei bando iš naujo. Kortelę į Done gali perkelti tik tu. Visa tai vyksta tavo kompiuteryje, be paskyrų, be sekliklių ir be slapukų. Ji kalba maždaug 120 kalbų, o draugai gali rašyti vieni kitiems privačiai ir užšifruotai. Ji dar nebaigta, uždara ankstyva alfa, bet jau dabar naudojasi pati savimi.","Maždaug toks AI-gile diena. Vakare palieki kelis komentarus: šis mygtukas ne toje vietoje, tą sąrašą reikia surikiuoti, gal galėtume turėti tamsią temą. Eini miegoti. Agentai perskaito komentarus, padaro pakeitimus, išbando ir grąžina tau. Jei stulpelis Ko reikia padaryti ištuštėja, naktinė sargyba papildo jį iš atsargų kortelėmis, kurioms tavo atsakymo nereikia. Ryte lieka viena trumpa krūvelė: pora klausimų ir keli dalykai išbandymui, kiekvienas su žingsniais, kuriuos gali atlikti ir mieguistas žmogus, bei ekrano nuotrauka, kad veikia. Perbėgi, priimi tinkamus ir grąžini likusius. Žetonų skaitiklis parodo, kiek viskas sunaudojo, o No Token Mode skirtas taupioms savaitėms. Tada pusryčiauji, kuriuose agentai kol kas padėti negali. Naktį lenta dirba už tave, o dieną sprendimus visada priimi tu. Jei kas nors nepavyko, tiesiog parašai komentarą, ir komanda pabunda iš naujo. Taip diena po dienos tavo idėjos keliauja iš minčių į veikiančią programą, o tu nepraleidi vakaro prie kodo.","Pirmiausia, kas AI-gile nėra. Tai ne startuolis, ji neparduodama ir niekas nerenka tavo duomenų. Tai nemokama lenta, veikianti tavo kompiuteryje, be paskyrų, sekliklių ir slapukų. O kas ji yra: viena tvarkinga vieta matyti visus dirbtinio intelekto programavimo projektus iš karto, kur agentų komanda atlieka korteles, o sprendimus priimi tu. Ji sujungia susijusias korteles, sutvarko painius pavadinimus ir stebi, kad kodas liktų lengvas. Ji kalba maždaug 120 kalbų, nuo olandų ir flamandų iki piratų ir klingonų. Draugai gali rašyti vieni kitiems, privačiai ir užšifruotai. Ją sukūrė Richas ir daugybė kantrių agentų, daugiausia naudodamiesi ja pačia. Ji yra uždaroje ankstyvoje alfoje, todėl kai kur šiurkšti. Jei skamba smagiai, paprašyk mandagiai, ir gal pateksi anksti. Mums patinka, kad ji lėta, kantri ir sąžininga: nieko neparduoda, nieko neslepia, tik tvarkingai laiko visus tavo projektus vienoje vietoje."]}],"quips":{"1":"Vienas žodis. Drąsu. Gal net per drąsu.","3":"Trys žodžiai. Jau sąžiningiau nei dauguma produktų puslapių.","8":"Aštuoni žodžiai. Vis tiek trumpiau nei stovimasis susitikimas.","21":"Beje, ilgiai yra istorijos taškai. Žinoma, kad taip.","55":"Penkiasdešimt penki žodžiai. Kol skaitei, baigtos dvi kortelės.","144":"Tai ilgiausia versija. 233 nėra. Agentai nuėjo miegoti."}},"timeline":{"first-idea.name":"Pirmoji idėja","first-idea.line":"Pats pirmas pokalbis, dar nesant nė eilutės kodo.","first-board.name":"Pirmoji lenta","first-board.line":"Lenta, sekanti savo paties kūrimą: kortelės, stulpeliai, tempimas, projektai.","team-roles.name":"Komanda ir vaidmenys","team-roles.line":"Agentų profiliai, komandų šablonai, erdvės ir kas ką daro.","install.name":"Diegimas ir leidimai","install.line":"Zip, kurį gali įsidiegti draugas, savaiminiai atnaujinimai, kanalai ir grąžinimas atgal.","usage-saver.name":"Sąnaudų taupymas","usage-saver.line":"Matuoja, kiek kainuoja paleidimai, laiko kodą lengvą ir taupo tavo limitą.","friends.name":"Draugai ir dalijimasis","friends.line":"Privačios žinutės, užšifruotas relay, kvietimai, vaidmenys ir bendri projektai.","languages.name":"Kalbos","languages.line":"Kiekvienas ekrano tekstas kalbos faile, pirmiausia olandų ir flamandų.","ai-tester.name":"Dirbtinio intelekto testuotojas","ai-tester.line":"Testuotojas pirmas patikrina kiekvieną perdavimą ir parodo, ką pamatė.","website.name":"Svetainė","website.line":"aigile.lol, pristatomasis puslapis ir ši laiko juosta.","streaming.name":"Pokalbiai ir transliacijos","streaming.line":"Discord, Twitch, OBS, transliuotojo režimas, GIF ir jaustukai.","no-ai.name":"Leidimas be dirbtinio intelekto","no-ai.line":"Lenta tiems, kurie programuoja be dirbtinio intelekto, ir vieši projektai.","night-watch.name":"Naktinė sargyba","night-watch.line":"Sargas ir Scrum Master palaiko komandų darbą, kol tu miegi.","p-more.name":"Visa kita","p-more.line":"Mažesnės idėjos, vis dar laukiančios savo eilės.","p-android.name":"Telefonas ir Android","p-android.line":"Pasiek savo lentą iš telefono, vėliau ir iš savos Android programos.","p-release.name":"Alfa ir toliau","p-release.line":"Uždara alfa, gyva svetainė, tada beta.","p-languages.name":"Daugiau kalbų","p-languages.line":"Daugiau nei šimtas kalbų ir panardinimo režimas besimokantiems.","p-engines.name":"Daugiau dirbtinio intelekto variklių","p-engines.line":"Kiekvienam agentui pasirink Claude, Codex ar Gemini.","p-pro.name":"Profesionali praktika","p-pro.line":"Rizikos žymos, sujungimo vartai, incidentų kortelės ir apsauginiai turėklai.","p-self.name":"Rūpinimasis tavimi","p-self.line":"Pavargimo režimas, priminimai pasirūpinti savimi ir 4:20.","p-servers.name":"Serveriai ir augimas","p-servers.line":"Bendri serverio nustatymai, vaidmenys ir augimo planavimas.","p-livestream.name":"Transliacijų priedai","p-livestream.line":"Twitch pokalbis, savi jaustukai ir vieša gyva peržiūra."},"words":{"button":"📖 Programuotojų žodžiai","h":"📖 Programuotojų žodžių aiškinimas","intro":"Žodžiai, kuriuos vartoja programuotojai (ir AI komandos), paprasta kalba.","search":"Ieškoti žodžio…","none":"Atitinkančių žodžių nėra.","close":"Uždaryti","list":[{"id":"backlog","word":"Backlog","text":"Idėjos ir darbai, kurie dar nesuplanuoti. Niekas iš to nedaroma, kol nepersikelia į Reikia padaryti."},{"id":"sprint","word":"Sprintas","text":"Trumpas darbo laikotarpis (dažnai savaitė ar dvi) su sutartu kortelių rinkiniu, kurį reikia baigti.","also":["sprints","sprint","sprintai"]},{"id":"standup","word":"Stand-up","text":"Greita apžvalga: ką kiekvienas padarė, ką daro toliau ir kas trukdo.","also":["standup","stand-ups","stand-up'ai"]},{"id":"bug","word":"Klaida","text":"Kažkas, kas neveikia taip, kaip turėtų.","also":["bug","bugs","bugai","klaidos"]},{"id":"test","word":"Testas","text":"Baigto darbo išbandymas, kad patikrintum, ar jis daro tai, ko prašyta, prieš jį priimant.","also":["test","tests","testai"],"noTip":1},{"id":"commit","word":"Commit","text":"Išsaugota kodo momentinė kopija su trumpa pastaba, kas pasikeitė. Prie bet kurios visada gali grįžti.","also":["commits","commit'ai","komitas"]},{"id":"push","word":"Push","text":"Išsaugotų momentinių kopijų (commit'ų) siuntimas iš šio kompiuterio į GitHub, kad jos būtų saugiai išsaugotos ir prieinamos kitiems."},{"id":"branch","word":"Branch","text":"Atskira darbo kodo šaka, kad pakeitimus būtų galima daryti neliečiant pagrindinės versijos.","also":["branches","šaka","šakos"]},{"id":"merge","word":"Merge","text":"Šakos pakeitimų sujungimas atgal į pagrindinę versiją."},{"id":"repo","word":"Repo","text":"Projekto kodo aplankas su visa commit'ų istorija, paprastai laikomas ir GitHub'e.","also":["repository","saugykla"]},{"id":"refactor","word":"Refactor","text":"Kodo sutvarkymas nekeičiant, ką jis daro: mažesni failai, aiškesni pavadinimai, mažiau pasikartojimų."},{"id":"deploy","word":"Deploy","text":"Naujos versijos paleidimas į gyvą aplinką, pavyzdžiui, serveryje, kuriuo žmonės naudojasi."},{"id":"kanban","word":"Kanban","text":"Lenta su stulpeliais (Reikia padaryti, Vykdoma, Atlikta), kurioje kortelės dirbant juda iš kairės į dešinę."},{"id":"wip","word":"WIP riba","text":"Vykdomas darbas: daugiausia kortelių, kiek gali turėti stulpelis, kad komanda baigtų darbus, prieš pradėdama naujus.","also":["WIP","vykdomo darbo riba"]},{"id":"pr","word":"Pull request","text":"Prašymas patikrinti šakos pakeitimus ir sujungti juos į pagrindinę versiją.","also":["PR"]},{"id":"hook","word":"Hook","text":"Mažas veiksmas, kuris pats įsijungia tam tikru momentu, pvz., kai prasideda AI sesija, kad komanda išgirstų tavo komentarus.","also":["hooks","kabliukas","kabliukai"]},{"id":"token","word":"Token","text":"Vienetas, kuriuo skaičiuojamas AI naudojimas: maždaug kelios perskaityto ar parašyto teksto raidės. Mažiau žetonų – daugiau plano lieka.","also":["tokens","žetonas","žetonai"]},{"id":"agent","word":"Agent","text":"AI, kuris savarankiškai dirba su užduotimi: skaito kodą, daro pakeitimus, vykdo patikras ir praneša.","also":["agents","agentas","agentai"]}]}};
